// Writes conformance/guarded-apply.v1.json: language-neutral scenarios generated by running the
// TypeScript editor. Each scenario is a document plus a sequence of transactions with the exact
// outcome the reference produced. Go and Python ports must reproduce every step.
import { writeFileSync } from 'node:fs';
import { createDocument, createEditor } from '../packages/core/src/index.js';
import type { Operation, ResearchDocument, Transaction } from '../packages/core/src/index.js';

let seed = 20261107;
const rand = (n: number): number => { seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0; return seed % n; };
const pick = <T,>(items: readonly T[]): T => items[rand(items.length)]!;
const clone = <T,>(value: T): T => JSON.parse(JSON.stringify(value)) as T;
const actor = { id: 'conformance-agent', kind: 'agent' } as const;

type Step = { now: string; transaction: Transaction; expect: { ok: true; duplicate?: true; document: ResearchDocument } | { ok: false; issues: { code: string; blockId?: string }[]; currentRevision: number } };

function scenario(index: number, length: number): { name: string; initial: ResearchDocument; steps: Step[] } {
  let tick = 0;
  const base = Date.UTC(2026, 10, 7, 9, 0, 0);
  const at = (): string => new Date(base + tick * 1000).toISOString().replace(/\.\d{3}Z$/, 'Z');
  let current = at();
  const initial = createDocument({ id: `doc-${index}`, title: `Scenario ${index}` }, { now: () => current });
  const editor = createEditor(initial, { now: () => current });
  const steps: Step[] = [];
  let ids = 0, txs = 0;
  let lastSuccess: Transaction | undefined, lastAny: Transaction | undefined;
  const fresh = (): string => `b${index}-${++ids}`;
  const paragraph = (): { type: 'paragraph'; runs: { text: string }[] } => ({ type: 'paragraph', runs: [{ text: `text ${rand(1000)}` }] });
  const blockInput = (id: string) => ({ id, parentId: null, content: paragraph(), citationIds: [] as string[] });
  for (let s = 0; s < length; s++) {
    tick += 1 + rand(3);
    current = at();
    const snap = editor.getSnapshot();
    const live = snap.blocks;
    const anyBlock = (): (typeof live)[number] | undefined => live.length ? pick(live) : undefined;
    const ops: Operation[] = [];
    let baseRevision = snap.revision;
    let id = `tx-${index}-${++txs}`;
    const kind = rand(100);
    const target = anyBlock();
    const anchorOf = (): { afterId?: string | null } => { const r = rand(4); return r === 0 ? {} : r === 1 ? { afterId: null } : live.length ? { afterId: pick(live).id } : {}; };
    if (kind < 22 || live.length === 0) ops.push({ type: 'insertBlock', block: blockInput(fresh()), ...anchorOf() } as Operation);
    else if (kind < 40) ops.push({ type: 'updateBlock', blockId: target!.id, expectedVersion: target!.version, content: paragraph() } as Operation);
    else if (kind < 50) { const others = live.filter(b => b.id !== target!.id); ops.push({ type: 'moveBlock', blockId: target!.id, expectedVersion: target!.version, parentId: null, ...(others.length && rand(2) ? { afterId: pick(others).id } : rand(3) === 0 ? { afterId: null } : {}) } as Operation); }
    else if (kind < 58) ops.push({ type: 'deleteBlock', blockId: target!.id, expectedVersion: target!.version } as Operation);
    else if (kind < 62) ops.push({ type: 'setTitle', title: `Title ${rand(100)}` } as Operation);
    else if (kind < 67) { const newId = fresh(); ops.push({ type: 'insertBlock', block: blockInput(newId) } as Operation, { type: 'updateBlock', blockId: newId, expectedVersion: 1, content: paragraph() } as Operation); }
    else if (kind < 71) ops.push({ type: 'updateBlock', blockId: target!.id, expectedVersion: target!.version, content: paragraph() } as Operation, { type: 'updateBlock', blockId: target!.id, expectedVersion: target!.version + 1, content: paragraph() } as Operation);
    // Invalid or edge cases below: the reference decides the outcome.
    else if (kind < 75) ops.push({ type: 'updateBlock', blockId: target!.id, expectedVersion: target!.version + 1 + rand(3), content: paragraph() } as Operation);
    else if (kind < 78) ops.push({ type: 'updateBlock', blockId: `missing-${rand(9)}`, expectedVersion: 1, content: paragraph() } as Operation);
    else if (kind < 81) ops.push({ type: 'insertBlock', block: blockInput(target!.id) } as Operation);
    else if (kind < 84) { const retired = snap.retiredBlockIds; ops.push({ type: 'insertBlock', block: blockInput(retired.length ? pick(retired) : target!.id) } as Operation); }
    else if (kind < 87) ops.push({ type: 'insertBlock', block: blockInput(fresh()), afterId: `nowhere-${rand(9)}` } as Operation);
    else if (kind < 89) ops.push({ type: 'moveBlock', blockId: target!.id, expectedVersion: target!.version, parentId: null, afterId: target!.id } as Operation);
    else if (kind < 92) { ops.push({ type: 'setTitle', title: 'Atomic title' } as Operation, { type: 'deleteBlock', blockId: target!.id, expectedVersion: target!.version } as Operation, { type: 'updateBlock', blockId: target!.id, expectedVersion: target!.version, content: paragraph() } as Operation); }
    else if (kind < 94) { ops.push({ type: 'setTitle', title: 'Stale title' } as Operation); baseRevision = snap.revision > 0 ? snap.revision - 1 : snap.revision + 1; }
    else if (kind < 96) { ops.push({ type: 'insertBlock', block: blockInput(fresh()) } as Operation); baseRevision = snap.revision + 2; }
    else if (kind < 98 && lastSuccess) { const retry = clone(lastSuccess); steps.push(record(retry)); continue; }
    else if (kind === 99) { current = new Date(Date.parse(snap.updatedAt) - 5000).toISOString().replace(/\.\d{3}Z$/, 'Z'); ops.push({ type: 'setTitle', title: 'Clock moved back' } as Operation); }
    else if (lastAny) { const reuse = { ...clone(lastAny), operations: [{ type: 'setTitle', title: 'Different payload' } as Operation] }; steps.push(record(reuse)); continue; }
    else ops.push({ type: 'setTitle', title: 'Fallback' } as Operation);
    const transaction: Transaction = { id, actor: clone(actor), baseRevision, operations: ops };
    steps.push(record(transaction));
  }
  function record(transaction: Transaction): Step {
    const result = editor.apply(transaction);
    lastAny = transaction;
    const nowStr = current;
    if (result.ok) {
      lastSuccess = transaction;
      return { now: nowStr, transaction, expect: { ok: true, ...(result.duplicate ? { duplicate: true as const } : {}), document: clone(result.document) } };
    }
    return { now: nowStr, transaction, expect: { ok: false, issues: result.issues.map(i => ({ code: i.code, ...(i.blockId ? { blockId: i.blockId } : {}) })), currentRevision: result.currentRevision } };
  }
  return { name: `random-${index}`, initial: clone(initial), steps };
}

const scenarios = Array.from({ length: 14 }, (_, i) => scenario(i, 22));
const all = scenarios.flatMap(s => s.steps);
const codes: Record<string, number> = {};
for (const step of all) { const key = step.expect.ok ? (step.expect.duplicate ? 'ok-duplicate' : 'ok') : step.expect.issues.map(i => i.code).join('+'); codes[key] = (codes[key] ?? 0) + 1; }
writeFileSync(new URL('../conformance/guarded-apply.v1.json', import.meta.url), `${JSON.stringify({
  version: 1,
  note: 'Generated by scripts/export-conformance.ts from the TypeScript reference. Flat documents of paragraph blocks; operations insertBlock, updateBlock, moveBlock, deleteBlock, setTitle. Steps run in order on one editor; now is the clock for that step.',
  scenarios,
}, null, 1)}\n`);
console.log(`${scenarios.length} scenarios, ${all.length} steps`, codes);
